"""Static candidate arithmetic; neither market simulation nor approved game data."""
import json
from pathlib import Path

OUT = Path(__file__).resolve().parents[2] / 'docs/development/economy-agent-sim-20260926/pro-recipes'
OUT.mkdir(exist_ok=True)
rows = []
for vector, bases in [('pro', [8,10,12,6]), ('import12_retail14', [14]*4), ('import6_retail8', [8]*4)]:
    for name, n, price, cash, raw in [
        ('filter',4,4,bases[0]+2,4), ('wrap',3,6,bases[1]+2,4),
        ('tin',4,5,bases[2]+2,4), ('salve',2,18,bases[3]+4+10+2,6)]:
        net=n*price*.95
        rows.append(dict(vector=vector,product=name,output=n,price=price,
            cash_profit=round(net-cash,4),opportunity_profit=round(net-cash-raw,4),
            break_even=(cash+raw)/(.95*n)))
leather=[dict(output=n,value=v,break_even=16/(.95*n),
              positive_interval=16/(.95*n)<v) for n in [1,3,6] for v in [6,8,10]]
(OUT/'calculation.json').write_text(json.dumps(dict(recipes=rows,leather=leather),indent=2)+'\n')
lines=['# Pro \u65b0\u914d\u65b9\u9759\u6001\u590d\u7b97','', '\u4ec5\u5019\u9009\u5047\u8bbe\u3002\u8d39\u73875%\uff0c\u5854\u6750\u673a\u4f1a\u4ef7\u503c4/4/4/6\u662f\u6d4b\u8bd5\u503c\uff0c\u672a\u9a8c\u8bc1\u53ef\u6210\u4ea4\uff1b\u5c0f\u6570\u8d39\u7528\u662f\u957f\u671f\u6bd4\u4f8b\u8fd1\u4f3c\uff0c\u6e38\u620f\u6574\u6570\u7ed3\u7b97\u9700\u4fdd\u7559\u624b\u7eed\u8d39\u4f59\u6570\u3002', '', '|\u6210\u672c\u5411\u91cf|\u4ea7\u54c1|\u6279\u6b21\u73b0\u91d1\u5229\u6da6|\u6279\u6b21\u673a\u4f1a\u5229\u6da6|\u5355\u4ef6\u673a\u4f1a\u6210\u672c\u4fdd\u672c\u4ef7|','|---|---|---:|---:|---:|']
